function companyCompositionMarkup(rows, days) { if (!rows.length) return '<p class=\'subtle\'>Composition history will appear after daily snapshots populate.</p>'; const latest = rows.at(-1); const cutoff = new Date(new Date(latest.day).getTime() - days * 86400000); const previous = rows.find((row) => new Date(row.day) <= cutoff) || rows[0]; const parse = (value) => typeof value === 'string' ? JSON.parse(value || '{}') : (value || {}); const groups = [['Specialties', parse(latest.specialty_counts), parse(previous.specialty_counts)], ['Technologies', parse(latest.technology_counts), parse(previous.technology_counts)], ['Work mode', parse(latest.work_mode_counts), parse(previous.work_mode_counts)], ['Employment type', parse(latest.employment_type_counts), parse(previous.employment_type_counts)]]; return '<p class=\'subtle\'>Latest snapshot ' + esc(date(latest.day)) + ' · compared with ' + esc(date(previous.day)) + ' · initial imports are excluded from new-activity counts.</p>' + groups.map(([label, current, prior]) => { const keys = [...new Set([...Object.keys(current), ...Object.keys(prior)])].sort((a, b) => Number(current[b] || 0) - Number(current[a] || 0)).slice(0, 10); return '<div class=\'composition-group\'><h3>' + esc(label) + '</h3>' + (keys.length ? keys.map((key) => { const delta = Number(current[key] || 0) - Number(prior[key] || 0); return '<div class=\'health-row\'><span>' + esc(key) + '</span><strong>' + Number(current[key] || 0).toLocaleString() + ' <small class=\'subtle\'>(' + (delta >= 0 ? '+' : '') + delta + ')</small></strong></div>'; }).join('') : '<p class=\'subtle\'>No classified values.</p>') + '</div>'; }).join(''); }
function renderCompanyComposition(data, days = 90) { const rows = data.dailyActivity || []; if (!$('#company-composition')) $('#company-profile').insertAdjacentHTML('afterbegin', '<div id=\'company-composition\' class=\'company-panel\'></div>'); $('#company-composition').innerHTML = '<div class=\'company-panel-heading\'><h2>Hiring composition</h2><label class=\'subtle\'>Window <select id=\'company-composition-window\'><option value=\'30\'>30 days</option><option value=\'90\'>90 days</option><option value=\'180\'>180 days</option></select></label></div>' + companyCompositionMarkup(rows, days); $('#company-composition-window').value = String(days); $('#company-composition-window').addEventListener('change', (event) => renderCompanyComposition(data, Number(event.target.value))); }
