loadMarketTrends = async function() { const data = await api('/api/market/trends?dimension=' + encodeURIComponent($('#market-trend-dimension').value) + '&cohort=' + encodeURIComponent($('#market-trend-cohort').value) + '&granularity=' + encodeURIComponent($('#market-trend-granularity').value)); const grouped = {}; for (const row of data.metrics || []) { grouped[row.snapshot_date] ||= []; grouped[row.snapshot_date].push(row); } const periods = Object.entries(grouped).slice(-14); $('#market-trends').innerHTML = periods.length ? '<div class=\'trend-table\'><div class=\'trend-row trend-header\'><span>Period</span><span>Observed stock · share · new flow</span></div>' + periods.map(([period, rows]) => '<div class=\'trend-row\'><span>' + esc(period) + '</span><span>' + rows.slice(0, 5).map((row) => '<span class=\'pill\'>' + esc(row.dimension_value) + ' · ' + Number(row.active_listings).toLocaleString() + ' (' + Math.round(Number(row.active_share || 0) * 100) + '%) · +' + Number(row.new_listings || 0).toLocaleString() + '</span>').join(' ') + '</span></div>').join('') + '</div><p class=\'subtle trend-coverage\'>Coverage: ' + Number((data.coverage || []).at(-1)?.monitored_boards || 0).toLocaleString() + ' monitored boards · ' + Number((data.coverage || []).at(-1)?.stable_boards || 0).toLocaleString() + ' stable boards · ' + Number((data.coverage || []).at(-1)?.newly_discovered_boards || 0).toLocaleString() + ' newly discovered on latest snapshot. ' + esc((data.coverage || []).at(-1)?.coverage_note || 'Snapshots begin after deployment.') + '</p>' : '<p class=\'subtle\'>No snapshots available yet. The worker creates one at startup and refreshes it hourly.</p>'; };
