loadMarketComparison = async function() { const categoryA = $('#market-compare-a').value; const categoryB = $('#market-compare-b').value; const workMode = $('#market-compare-work-mode').value; const employmentType = $('#market-compare-employment').value; if (!categoryA || !categoryB) { $('#market-comparison').innerHTML = '<p class=\'subtle\'>Choose two categories to compare.</p>'; return; } const encodeSegment = (category) => JSON.stringify({ category, workMode, employmentType }); const data = await api('/api/market/compare?a=' + encodeURIComponent(encodeSegment(categoryA)) + '&b=' + encodeURIComponent(encodeSegment(categoryB))); const a = data.segments.a; const b = data.segments.b; const number = (value) => Number(value || 0).toLocaleString(); const percent = (value) => Math.round(Number(value || 0) * 100) + '%'; $('#market-comparison').innerHTML = [['Active listings', number(a.totals.active_listings), number(b.totals.active_listings)], ['New listings · 7d', number(a.totals.new_listings_last_7_days), number(b.totals.new_listings_last_7_days)], ['Employers', number(a.totals.monitored_employers), number(b.totals.monitored_employers)], ['Remote share', percent(a.shares.remote), percent(b.shares.remote)], ['Contract share', percent(a.shares.contract), percent(b.shares.contract)], ['Salary coverage', percent(a.shares.salary_coverage), percent(b.shares.salary_coverage)], ['Top specialties', (a.topSpecialties || []).slice(0, 3).map((item) => item.value + ' (' + number(item.count) + ')').join(', ') || '—', (b.topSpecialties || []).slice(0, 3).map((item) => item.value + ' (' + number(item.count) + ')').join(', ') || '—']].map(([label, valueA, valueB]) => '<div class=\'comparison-card\'><span>' + esc(label) + '</span><strong>' + esc(String(valueA)) + ' <small>vs</small> ' + esc(String(valueB)) + '</strong></div>').join(''); };
