const marketUrlParams = new URLSearchParams(location.search);
for (const [id, key] of [['market-active','active'],['market-category','category'],['market-provider','provider'],['market-specialty','specialty'],['market-work-mode','workMode'],['market-eligibility','remoteEligibility'],['market-region','region'],['market-country','country'],['market-technology','technology'],['market-employment','employmentType'],['market-seniority','seniority'],['market-location','location'],['market-employer','employer'],['market-currency','salaryCurrency'],['market-min-salary','minSalary'],['market-max-salary','maxSalary'],['market-max-age','maxAgeDays'],['market-published-after','publishedAfter'],['market-published-before','publishedBefore'],['market-first-observed','firstObservedAfter'],['market-search','q'],['market-sort','sort']]) { const value = marketUrlParams.get(key); if (value && $('#' + id)) $('#' + id).value = value; }

// Keep in-app navigation in the browser history so Back returns to the exact list context.
const appNavigation = { handlingRoute: false, preserveListingReset: false, preserveCompanyReset: false };
const nativeReplaceState = history.replaceState.bind(history);
const navigationUrl = (hash = location.hash) => `${location.pathname}${location.search}${hash || ''}`;
history.replaceState = (stateValue, title, url) => nativeReplaceState(stateValue, title, typeof url === 'string' && location.hash && !url.includes('#') ? `${url}${location.hash}` : url);
const validNavigationViews = new Set(['listings', 'feed', 'posts', 'market', 'companies', 'tasks', 'monitoring', 'rules', 'authors', 'company-profile']);
function navigationRoute() {
  const parts = decodeURIComponent(location.hash.replace(/^#/, '')).split('/').filter(Boolean);
  const listingIndex = parts.indexOf('listing');
  if (listingIndex > 0 && parts[listingIndex + 1]) return { kind: 'listing', id: parts[listingIndex + 1], parentHash: `#${parts.slice(0, listingIndex).join('/')}`, parentView: parts[0] === 'companies' && parts[1] === 'company' ? 'company-profile' : parts[0] };
  const companyIndex = parts.indexOf('company');
  if (companyIndex === 0 && parts[1]) return { kind: 'company', id: parts[1], view: 'company-profile' };
  if (parts[0] === 'tasks') return { kind: 'view', view: 'tasks', taskKind: ['social', 'listing', 'enrichment'].includes(parts[1]) ? parts[1] : 'social' };
  const view = validNavigationViews.has(parts[0]) ? parts[0] : 'listings';
  return { kind: 'view', view };
}
function saveNavigationPosition() { nativeReplaceState({ ...(history.state || {}), scrollY: window.scrollY }, '', navigationUrl()); }
function pushNavigation(hash, extraState = {}) { saveNavigationPosition(); history.pushState({ ...(history.state || {}), ...extraState, scrollY: 0 }, '', navigationUrl(hash)); }
function restoreNavigationPosition(stateValue) { requestAnimationFrame(() => window.scrollTo({ top: Number(stateValue?.scrollY || 0), left: 0, behavior: 'auto' })); }
function closeListingDrawer() { $('#drawer')?.classList.add('hidden'); }

const navigationBaseShowView = showView;
showView = function(view) {
  navigationBaseShowView(view);
  if (appNavigation.handlingRoute) return;
  const route = navigationRoute();
  if (route.kind === 'view' && route.view === view) return;
  pushNavigation(`#${view}`);
  restoreNavigationPosition({ scrollY: 0 });
};

const navigationBaseLoadListings = loadListings;
loadListings = async function(resetPage = false) {
  const preservePage = appNavigation.preserveListingReset;
  appNavigation.preserveListingReset = false;
  return navigationBaseLoadListings(preservePage ? false : resetPage);
};
const navigationBaseLoadCompanies = loadCompanies;
loadCompanies = async function(resetPage = false) {
  const preservePage = appNavigation.preserveCompanyReset;
  appNavigation.preserveCompanyReset = false;
  return navigationBaseLoadCompanies(preservePage ? false : resetPage);
};
document.addEventListener('click', (event) => {
  const tab = event.target.closest('.tab');
  if (tab?.dataset.view === 'listings') appNavigation.preserveListingReset = true;
  if (tab?.dataset.view === 'companies') appNavigation.preserveCompanyReset = true;
}, true);

const navigationBaseOpenCompany = openCompany;
openCompany = async function(id, options = {}) {
  if (!options.fromHistory && !appNavigation.handlingRoute) {
    saveNavigationPosition();
    pushNavigation(`#companies/company/${encodeURIComponent(id)}`);
  }
  appNavigation.handlingRoute = true;
  try { return await navigationBaseOpenCompany(id); } finally { appNavigation.handlingRoute = false; }
};
const navigationBaseOpenListing = openListing;
openListing = async function(id, options = {}) {
  if (!options.fromHistory && !appNavigation.handlingRoute) {
    const route = navigationRoute();
    const parentHash = location.hash && (route.kind === 'view' || route.kind === 'company') ? location.hash : (route.parentHash || '#listings');
    saveNavigationPosition();
    pushNavigation(`${parentHash.replace(/\/$/, '')}/listing/${encodeURIComponent(id)}`);
  }
  return navigationBaseOpenListing(id);
};

document.querySelectorAll('.tab').forEach((tab) => tab.addEventListener('click', () => showView(tab.dataset.view)));
document.querySelector('#close-drawer')?.addEventListener('click', () => { if (navigationRoute().kind === 'listing') history.back(); });
document.querySelector('.drawer-backdrop')?.addEventListener('click', () => { if (navigationRoute().kind === 'listing') history.back(); });
document.addEventListener('click', (event) => { if (event.target.closest('#drawer .listing-action') && navigationRoute().kind === 'listing') history.back(); }, true);

async function applyNavigationRoute(initial = false) {
  const route = navigationRoute();
  closeListingDrawer();
  if (route.kind === 'listing') {
    appNavigation.handlingRoute = true;
    try {
      navigationBaseShowView(route.parentView);
      await openListing(route.id, { fromHistory: true });
    } finally { appNavigation.handlingRoute = false; }
    restoreNavigationPosition(history.state);
    return;
  }
  if (route.kind === 'company') {
    await openCompany(route.id, { fromHistory: true });
    restoreNavigationPosition(history.state);
    return;
  }
  appNavigation.handlingRoute = true;
  navigationBaseShowView(route.view);
  appNavigation.handlingRoute = false;
  if (initial && route.view === 'companies') await loadCompanies();
  if (initial && route.view === 'feed') await loadCompanySignals(true);
  if (initial && route.view === 'posts') await loadPostDiscovery(true);
  if (initial && route.view === 'market' && typeof loadMarket === 'function') await loadMarket();
  if (route.view === 'tasks') await loadTaskPanel(route.taskKind || 'social');
  restoreNavigationPosition(history.state);
}
if (!location.hash) nativeReplaceState({ view: 'listings', scrollY: 0 }, '', navigationUrl('#listings'));
window.addEventListener('popstate', () => applyNavigationRoute().catch(console.error));
window.addEventListener('load', () => applyNavigationRoute(true).catch(console.error));

const renderCompanyProfileWithBoardLinks = renderCompanyProfile;
let companyEmailSourceData = new Map();
function closeEmailSourcesModal() { $('#email-sources-modal')?.classList.add('hidden'); }
function openEmailSourcesModal(emailId) {
  const email = companyEmailSourceData.get(emailId);
  if (!email) return;
  const sources = (Array.isArray(email.sources) ? email.sources : []).filter((source) => source.sourceType === 'job_listing');
  $('#email-sources-title').textContent = `Listings containing ${email.email}`;
  $('#email-sources-subtitle').textContent = `${sources.length} listing${sources.length === 1 ? '' : 's'} found · ${email.category || 'other'}`;
  $('#email-sources-list').innerHTML = sources.length ? sources.map((source) => {
    const url = source.listingUrl || source.sourceUrl;
    const title = source.listingTitle || 'Job listing';
    return `<div class="email-source-row"><div><strong>${esc(title)}</strong><small class="subtle">${esc(source.sourceType === 'job_listing' ? 'Job listing' : 'Company page')}</small></div>${url ? `<a class="source-link" href="${esc(url)}" target="_blank" rel="noreferrer">Open listing ↗</a>` : ''}</div>`;
  }).join('') : '<p class="subtle">No listing sources are currently active.</p>';
  $('#email-sources-modal').classList.remove('hidden');
}
document.addEventListener('click', (event) => {
  const button = event.target.closest('.company-email-see-all');
  if (button) openEmailSourcesModal(button.dataset.emailId);
});
$('#close-email-sources')?.addEventListener('click', closeEmailSourcesModal);
$('.email-sources-backdrop')?.addEventListener('click', closeEmailSourcesModal);
renderCompanyProfile = function(data) {
  renderCompanyProfileWithBoardLinks(data);
  const company = data.company || {};
  if (company.website || company.career_url) $('#company-profile-subtitle').innerHTML = [company.website ? `<a class="source-link" href="${esc(company.website)}" target="_blank" rel="noreferrer">${esc(company.website)} ↗</a>` : '', company.career_url ? `<a class="source-link" href="${esc(company.career_url)}" target="_blank" rel="noreferrer">Careers ↗</a>` : ''].filter(Boolean).join(' · ');
  const socialLinks = data.socialLinks || [];
  const emails = data.emails || [];
  companyEmailSourceData = new Map(emails.map((email) => [String(email.id), email]));
  const profileGrid = document.querySelector('#company-profile .company-profile-grid');
  profileGrid?.classList.add('company-details-grid');
  const platformLabel = { bluesky: 'Bluesky', mastodon: 'Mastodon', youtube: 'YouTube', linkedin: 'LinkedIn', facebook: 'Facebook', x: 'X' };
  const socialActivity = data.socialActivity || [];
  const socialTimeline = socialActivity.length ? socialActivity.map((post) => `<article class="company-social-post"><div class="company-social-post-top"><span class="source-label"><b>${esc(platformLabel[post.platform] || post.platform)}</b> · ${esc(post.author_name || post.author_handle || 'Company account')}</span><span class="subtle">${relative(post.published_at)}</span></div><p>${esc(post.text)}</p><div class="opp-meta"><span>${esc(post.author_handle || '')}</span><a class="source-link" href="${esc(post.source_url)}" target="_blank" rel="noreferrer">View original ↗</a></div></article>`).join('') : '<p class="subtle">No recent original public posts have been collected yet.</p>';
  if (profileGrid) {
    profileGrid.insertAdjacentHTML('beforeend', `<div class="company-panel company-social-panel"><div class="company-panel-heading"><h2>Social profiles</h2><span class="subtle">${socialLinks.length} discovered</span></div>${socialLinks.length ? socialLinks.map((link) => `<div class="health-row"><span>${esc(platformLabel[link.platform] || link.platform)}</span><a class="source-link" href="${esc(link.profile_url)}" target="_blank" rel="noreferrer">Open profile ↗</a></div>`).join('') : '<p class="subtle">No explicit social profiles found yet.</p>'}</div>`);
    const emailRows = emails.map((email) => {
      const sources = Array.isArray(email.sources) ? email.sources : [];
      const listingSources = sources.filter((source) => source.sourceType === 'job_listing');
      const primarySource = sources.find((source) => source.sourceType === 'company_page') || listingSources[0];
      const primaryUrl = primarySource?.sourceType === 'job_listing' ? (primarySource.listingUrl || primarySource.sourceUrl) : primarySource?.sourceUrl;
      const primaryLabel = primarySource?.sourceType === 'job_listing' ? (primarySource.listingTitle || 'Job listing') : 'Company page';
      const primaryLink = primarySource ? (primaryUrl ? `<a class="source-link" href="${esc(primaryUrl)}" target="_blank" rel="noreferrer">${esc(primaryLabel)} ↗</a>` : esc(primaryLabel)) : '<span class="subtle">Source unavailable</span>';
      const seeAll = listingSources.length > 1 ? `<button type="button" class="button secondary email-source-button company-email-see-all" data-email-id="${esc(String(email.id))}">See all ${listingSources.length} listings</button>` : '';
      return `<div class="health-row company-email-row"><span><a class="source-link" href="mailto:${esc(email.email)}">${esc(email.email)}</a><small class="subtle"> · ${esc(String(email.category || 'other'))}</small></span><span class="company-email-sources"><span>${primaryLink}</span>${seeAll}</span></div>`;
    }).join('');
    profileGrid.insertAdjacentHTML('beforeend', `<div class="company-panel company-email-panel"><div class="company-panel-heading"><h2>Public emails</h2><span class="subtle">${emails.length} active</span></div>${emailRows || '<p class="subtle">No public emails found yet.</p>'}</div>`);
    profileGrid.insertAdjacentHTML('afterend', `<div class="company-panel company-social-activity"><div class="company-panel-heading"><div><h2>Social activity</h2><p class="subtle">Original public posts from discovered company accounts · latest 50</p></div></div><div class="company-social-timeline">${socialTimeline}</div></div>`);
  }
  const boardPanel = [...document.querySelectorAll('#company-profile .company-panel')].find((panel) => panel.querySelector('h2')?.textContent.trim() === 'ATS boards');
  if (!boardPanel) return;
  const rows = boardPanel.querySelectorAll('.health-row');
  (data.boards || []).forEach((board, index) => {
    const label = `${board.provider} · ${board.board_identifier}`;
    const url = (() => { try { const parsed = new URL(board.board_url || ''); return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : ''; } catch { return ''; } })();
    const row = rows[index];
    const value = row?.querySelector('span');
    if (!value) return;
    value.innerHTML = `${url ? `<a class="source-link" href="${esc(url)}" target="_blank" rel="noreferrer">${esc(label)} ↗</a>` : esc(label)}<small class="subtle">${board.status === 'active' ? ' · active' : ' · disabled'}</small>`;
  });
};

async function loadCompanyEnrichmentTasks() {
  const data = await api('/api/company-enrichment-tasks?limit=500&historyLimit=100');
  const active = data.active || [];
  const completed = data.history || [];
  const running = active.filter((task) => task.status === 'running').length;
  const queued = active.length - running;
  $('#task-panel').innerHTML = taskPanelMarkup(data, 'enrichment');
  $('#refresh-task-panel')?.addEventListener('click', () => loadTaskPanel('enrichment').catch(console.error));
}
